#define N 1000
int A[N], B[N];
const int UNROLL_FACTOR = 4;

// High pipeline efficiency: Increased ILP
// Branch prediction overhead reduced (N/4 cycles)
void process_unrolled() {
    for (int i = 0; i < N; i += UNROLL_FACTOR) {
        A[i]     += B[i];
        A[i+1]   += B[i+1];
        A[i+2]   += B[i+2];
        A[i+3]   += B[i+3];
    }
}

// Low pipeline efficiency: Standard Loop
// Frequent branch prediction stalls (N cycles)
void process_standard() {
    for (int i = 0; i < N; ++i) {
        A[i] += B[i];
    }
}
